<script>
import Layout from "../../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      depreciation: [],
      users: [],
      Users: {},
      page: 1,
      limit: 20,
      tot_pages: 0,
      searchUsers: null,
      SearchMode: false,
      emps: [],
      new_roles: [],
      newRoles: [{}],
      addRoles: [{}],
      branches: [],
      user_info: {},
      new_pass: "",
      users_switch: "",
      user_status: 0,
      data: {},

      // appprices:[]
    };
  },
  methods: {
    editUser() {
      console.log(this.user_info);
      this.http
        .put("users/", this.user_info.id, {
          new_roles: this.newRoles,
          name: this.user_info.name,
          email: this.user_info.email,
          branch: this.user_info.emp.branch.name,
        })
        .then(() => {
          this.get(this.page);
          console.log(this.newRoles);
        });
    },
    addUsers() {
      this.data.new_roles = this.addRoles;
      this.http.post("users/register", this.data).then(() => {
        this.data = {};
        this.addRoles = [{}];
        this.get(this.page);
      });
    },
    search() {
      this.SearchMode = true;
      console.log(this.searchUsers);
      this.tot_pages = 0;
      this.http
        .post("users/search", {
          limit: this.limit,
          page: this.page,
          search: this.searchUsers,
          col: "name",
        })
        .then((res) => {
          this.users = res.data;
        });
    },
    cancelSearchMode() {
      this.searchUsers = "";
      this.SearchMode = false;
      this.get(this.page);
    },
    getUsers() {
      this.http.get("users").then((res) => {
        this.users = res.data;
      });
    },
    deleteUser(user) {
      var data = {
        title: "popups.deleteuser",
        msg: "popups.deletemsg",
        buttons: [
          {
            text: "Delete",
            closer: true,
            color: "danger",
            handler: () => {
              console.log(user);
              this.http.delete("users", user.id).then(() => {
                this.get(this.page);
              });
            },
          },
          {
            text: "Cancel",
            closer: true,
            color: "light",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.confirm(data);
    },
    userInfo(user) {
      this.user_info = user;
      console.log(this.user_info);
    },
    editPass() {
      console.log(this.user_info.id);
      this.http.post("users/update-password", {
        user_id: this.user_info.id,
        pass: this.new_pass,
      });
    },

    get(page) {
      console.log(this.userstable);
      this.http
        .post("transactions/depreciation", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.depreciation = res.data;
        });
    },
    getEmp() {
      this.http.get("emps").then((res) => {
        this.emps = res.data;
      });
    },
    getRole() {
      this.http.get("roles").then((res) => {
        this.roles = res.data;
      });
    },
    getBransh() {
      this.http.get("branches").then((res) => {
        this.branches = res.data;
      });
    },
    getSwitch(user, status) {
      console.log(status);
      this.http
        .post("users/update-status", {
          status: status,
          user_id: user.id,
        })
        .then(() => {
          this.get(this.page);
        });
    },
  },
  created() {
    this.get(1);
  },
};
</script>

