              <input
                id="user"
                required
                class="form-control"
                type="text"
                :placeholder="$t('popups.username')"
                v-model="data.name"
              />

              <label for="user">{{ $t("popups.email") }}</label>
              <input
                v-model="data.email"
                id="user"
                required
                class="form-control"
                type="text"
                :placeholder="$t('popups.email')"
              />

              <label for="user_branch">{{ $t("popups.branch") }}</label>

              <select
                v-model="user_info.branch"
                required
                id="user_branch"
                class="form-select"
              >
                <option
                  v-for="branch in branches"
                  :key="branch"
                  :value="branch.id"
                >
                  {{ branch.name }}
                </option>
              </select>
              <div class="row d-flex align-items-center">
                <div class="col">
                  <label for="user_role">{{ $t("popups.role") }}</label>
                </div>
                <div class="col d-flex justify-content-end">
                  <button
                    type="button"
                    @click="newRoles.push({})"
                    class="btn float-end"
                  >
                    <span
                      class="bx bxs-plus-circle float-end fa-2x"
                      style="color: #2a3042 !important"
                    ></span>
                  </button>
                </div>
              </div>
              <div v-for="role in newRoles" :key="role">
                <select
                  required
                  v-model="role.role_id"
                  class="form-select mb-2"
                  id="user_role"
                >
                  <option v-for="r in roles" :key="r" :value="r.id">
                    {{ r.role }}
                  </option>
                </select>
              </div>
            </div>
            <div class="modal-footer" :dir="$i18n.locale == 'ar' ? 'rtl' : ''">
              <button type="submit" class="btn btn-primary">
                {{ $t("popups.edit") }}
              </button>
              <button
                data-bs-dismiss="modal"
